package com.bank.ccr.security; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; @Configuration public class SecurityConfig { @Value("${app.security.mode:local}") String mode; @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception { h.csrf(c->c.disable()); if("oidc".equalsIgnoreCase(mode)) h.authorizeHttpRequests(a->a.requestMatchers("/actuator/health").permitAll().requestMatchers("/api/admin/**").hasRole("CCR_ADMIN").anyRequest().hasAnyRole("CCR_ANALYST","CCR_ADMIN")).oauth2ResourceServer(o->o.jwt(j->{})); else h.authorizeHttpRequests(a->a.anyRequest().permitAll()); return h.build(); } }
